/**
 * Resolve, read and hash the rule/skill a proposal targets.
 *
 * Project and objective files live under `groups/`, which the board can write.
 * Entries there may be symlinks generated by `carapa-agent-view` that point at
 * shared template files; those are read for previews but never written through.
 */
import { createHash } from 'node:crypto';
import fs from 'node:fs';
import fsp from 'node:fs/promises';
import type { FileHandle } from 'node:fs/promises';
import path from 'node:path';
import { getProposalTemplateRoots } from '../../config.js';
import { getGroupDir } from '../../group-dir.js';
import { isPathInside } from '../../lib/path-containment.js';
import {
  itemEntryFile,
  ProposalValidationError,
  type ProposalAction,
  type ItemProposalKind,
  type TargetLayer,
  MAX_FILE_BYTES,
  setLocalFrontmatter,
} from './actions.js';
import { lineDiff } from './diff.js';
import { fdPath, openChain, openDirNoFollow } from './safe-fs.js';

const { O_RDONLY, O_NOFOLLOW } = fs.constants;

export interface TargetRef {
  project_id: string;
  objective_id: string | null;
  kind: ItemProposalKind;
  name: string;
  target_layer: TargetLayer;
}

export interface ItemTarget {
  /** The project's group directory: the root every target must stay inside. */
  rootDir: string;
  /** Path segments below `rootDir` of the rules/skills directory. */
  containerSegments: string[];
  containerDir: string;
  /** Absolute path of the rule file or skill folder (display only). */
  itemPath: string;
  /** Entry name inside the container directory. */
  itemName: string;
  kind: ItemProposalKind;
  name: string;
}

export function resolveTarget(ref: TargetRef): ItemTarget {
  const rootDir = getGroupDir(ref.project_id);
  let scope: string[];
  if (ref.target_layer === 'project') {
    scope = [];
  } else if (ref.target_layer === 'objective') {
    if (!ref.objective_id) {
      throw new ProposalValidationError(
        'An objective-layer proposal needs an objective_id',
      );
    }
    // Same location as getObjectiveDir(), kept as segments so every link in
    // the chain can be checked.
    scope = ['objectives', ref.objective_id];
  } else {
    throw new ProposalValidationError(
      `Target layer "${ref.target_layer}" is not supported yet`,
    );
  }
  const containerSegments = [
    ...scope,
    '.agent',
    ref.kind === 'skill' ? 'skills' : 'rules',
  ];
  const containerDir = path.join(rootDir, ...containerSegments);
  const itemName = ref.kind === 'skill' ? ref.name : `${ref.name}.md`;
  const itemPath = path.join(containerDir, itemName);
  return {
    rootDir,
    containerSegments,
    containerDir,
    itemPath,
    itemName,
    kind: ref.kind,
    name: ref.name,
  };
}

async function lstatOrNull(p: string) {
  try {
    return await fsp.lstat(p);
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null;
    throw err;
  }
}

/**
 * Run `fn` against the target's rules/skills directory, opened one verified
 * directory at a time (no symlinks below the project root). `dir` is a
 * descriptor-anchored path, so a later swap of any parent for a link cannot
 * redirect what `fn` reads, writes or deletes. `dir` is null when the
 * directory does not exist and `create` is false.
 */
export async function withContainer<T>(
  target: ItemTarget,
  create: boolean,
  fn: (dir: string | null) => Promise<T>,
): Promise<T> {
  const handle = await openChain(
    target.rootDir,
    target.containerSegments,
    create,
  );
  try {
    return await fn(handle ? fdPath(handle) : null);
  } finally {
    await handle?.close();
  }
}

/** Like withContainer, creating the directory chain (never through a link). */
export function withCreatedContainer<T>(
  target: ItemTarget,
  fn: (dir: string) => Promise<T>,
): Promise<T> {
  return withContainer(target, true, (dir) => fn(dir!));
}

const MAX_SNAPSHOT_ENTRIES = 500;
const MAX_SNAPSHOT_DEPTH = 8;
/** Largest single file a snapshot holds in full. */
const MAX_SNAPSHOT_FILE_BYTES = MAX_FILE_BYTES * 4;
const MAX_SNAPSHOT_BYTES = 2 * 1024 * 1024;

export interface ItemSnapshot {
  exists: boolean;
  /** The item itself is a symlink (generated link to a shared file). */
  symlink: boolean;
  symlinkTarget: string | null;
  /**
   * The item is a symlink resolving outside the project and the trusted
   * template roots. Its content is never read, so there is no authoritative
   * snapshot and actions on it are refused.
   */
  contentHidden: boolean;
  /**
   * Why the snapshot does not hold the item's complete content (size or entry
   * limits, special files, concurrent change). Such a snapshot cannot back a
   * hash or a preview, so actions on the item are refused.
   */
  incomplete: string | null;
  /** Relative path -> complete content. Rules hold a single `<name>.md` entry. */
  files: Map<string, Buffer>;
}

interface ReadState {
  files: Map<string, Buffer>;
  bytes: number;
  incomplete: string | null;
}

/** Read a whole file, or record why it cannot be held in full. */
async function readComplete(
  handle: FileHandle,
  rel: string,
  state: ReadState,
): Promise<void> {
  const { size } = await handle.stat();
  if (size > MAX_SNAPSHOT_FILE_BYTES) {
    state.incomplete = `"${rel}" is ${size} bytes; the limit is ${MAX_SNAPSHOT_FILE_BYTES}`;
    return;
  }
  if (state.bytes + size > MAX_SNAPSHOT_BYTES) {
    state.incomplete = `the item is larger than ${MAX_SNAPSHOT_BYTES} bytes`;
    return;
  }
  const content = await handle.readFile();
  state.bytes += content.length;
  state.files.set(rel, content);
}

/** Read a directory held open by `dir`, opening every child without following links. */
async function readTree(
  dir: FileHandle,
  prefix: string,
  state: ReadState,
  depth: number,
): Promise<void> {
  if (depth > MAX_SNAPSHOT_DEPTH) {
    state.incomplete = `folders nested deeper than ${MAX_SNAPSHOT_DEPTH}`;
    return;
  }
  const base = fdPath(dir);
  const entries = await fsp.readdir(base, { withFileTypes: true });
  entries.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
  for (const entry of entries) {
    if (state.incomplete) return;
    if (state.files.size >= MAX_SNAPSHOT_ENTRIES) {
      state.incomplete = `more than ${MAX_SNAPSHOT_ENTRIES} files`;
      return;
    }
    const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
    if (entry.isSymbolicLink()) {
      state.files.set(
        rel,
        Buffer.from(`symlink:${await fsp.readlink(`${base}/${entry.name}`)}`),
      );
    } else if (entry.isDirectory()) {
      const child = await openDirNoFollow(base, entry.name, rel).catch(
        () => null,
      );
      if (!child) {
        state.incomplete = `"${rel}" changed while it was being read`;
        return;
      }
      try {
        await readTree(child, rel, state, depth + 1);
      } finally {
        await child.close();
      }
    } else if (entry.isFile()) {
      const file = await fsp
        .open(`${base}/${entry.name}`, O_RDONLY | O_NOFOLLOW)
        .catch(() => null);
      if (!file) {
        state.incomplete = `"${rel}" changed while it was being read`;
        return;
      }
      try {
        await readComplete(file, rel, state);
      } finally {
        await file.close();
      }
    } else {
      state.incomplete = `"${rel}" is not a regular file`;
      return;
    }
  }
}

/** Fill the read state from an open item (file or directory). */
async function readOpenItem(
  handle: FileHandle,
  name: string,
  state: ReadState,
) {
  const stat = await handle.stat();
  if (stat.isDirectory()) await readTree(handle, '', state, 0);
  else if (stat.isFile()) await readComplete(handle, name, state);
  else state.incomplete = `"${name}" is not a regular file or folder`;
}

/**
 * Whether an opened descriptor refers to a path inside the project or a
 * trusted template root. The kernel reports the opened inode's real path, so
 * this holds for what was actually opened, whatever the link did meanwhile.
 */
async function openedInsideTrustedRoots(
  handle: FileHandle,
  projectRoot: string,
) {
  const real = await fsp.readlink(fdPath(handle)).catch(() => null);
  if (!real) return false;
  for (const root of [projectRoot, ...getProposalTemplateRoots()]) {
    const realRoot = await fsp.realpath(root).catch(() => null);
    if (realRoot && isPathInside(realRoot, real)) return true;
  }
  return false;
}

function absentSnapshot(): ItemSnapshot {
  return {
    exists: false,
    symlink: false,
    symlinkTarget: null,
    contentHidden: false,
    incomplete: null,
    files: new Map(),
  };
}

export async function readSnapshot(target: ItemTarget): Promise<ItemSnapshot> {
  return withContainer(target, false, async (dir) => {
    if (!dir) return absentSnapshot();
    const child = `${dir}/${target.itemName}`;
    const lstat = await lstatOrNull(child);
    if (!lstat) return absentSnapshot();
    const state: ReadState = { files: new Map(), bytes: 0, incomplete: null };
    const result = (
      symlink: boolean,
      symlinkTarget: string | null,
      contentHidden: boolean,
    ): ItemSnapshot => ({
      exists: true,
      symlink,
      symlinkTarget,
      contentHidden,
      incomplete: state.incomplete,
      files: state.files,
    });

    if (!lstat.isSymbolicLink()) {
      const handle = await fsp
        .open(child, O_RDONLY | O_NOFOLLOW)
        .catch(() => null);
      if (!handle) {
        state.incomplete = `${target.itemPath} changed while it was being read`;
        return result(false, null, false);
      }
      try {
        await readOpenItem(handle, target.itemName, state);
      } finally {
        await handle.close();
      }
      return result(false, null, false);
    }

    // A generated link: follow it only to read, and only if the inode that was
    // actually opened lies inside the project or a trusted template root.
    const symlinkTarget = await fsp.readlink(child);
    const handle = await fsp.open(child, O_RDONLY).catch(() => null);
    if (!handle) {
      // Dangling: nothing to read, and a later target changes the hash.
      return result(true, symlinkTarget, false);
    }
    try {
      if (!(await openedInsideTrustedRoots(handle, target.rootDir))) {
        return result(true, symlinkTarget, true);
      }
      await readOpenItem(handle, target.itemName, state);
    } finally {
      await handle.close();
    }
    return result(true, symlinkTarget, false);
  });
}

export function hashSnapshot(snapshot: ItemSnapshot): string {
  const hash = createHash('sha256');
  hash.update(
    `exists=${snapshot.exists};symlink=${snapshot.symlinkTarget ?? ''};hidden=${snapshot.contentHidden};incomplete=${snapshot.incomplete ?? ''}\n`,
  );
  for (const rel of [...snapshot.files.keys()].sort()) {
    const content = snapshot.files.get(rel)!;
    hash.update(`${rel}\0${content.length}\0`);
    hash.update(content);
  }
  return hash.digest('hex');
}

/** `unknown`: the previous content was not kept, so no change can be told. */
type FileChange = 'added' | 'modified' | 'removed' | 'unchanged' | 'unknown';

export interface PreviewFile {
  path: string;
  change: FileChange;
  diff: string;
}

export interface ActionPreview {
  actionType: ProposalAction['type'];
  /** Absolute path the action touches (rule file or skill folder). */
  targetPath: string;
  exists: boolean;
  /** The current entry is a symlink; Approve replaces it with a real item. */
  replacesSymlink: boolean;
  symlinkTarget: string | null;
  /** The current entry links outside the project; its content is not shown. */
  contentHidden: boolean;
  files: PreviewFile[];
  /** Why the action cannot run now, when known (shown instead of a diff). */
  problem: string | null;
  /** Platform/template layers: the repository commit Approve will make. */
  promotion?: {
    repository: string;
    branch: string;
    paths: string[];
    /** False for a proposal stored before the previous content was kept. */
    previousContentAvailable: boolean;
  };
}

export function fileChange(
  before: Buffer | undefined,
  after: Buffer | undefined,
) {
  const change: FileChange = !before
    ? 'added'
    : !after
      ? 'removed'
      : before.equals(after)
        ? 'unchanged'
        : 'modified';
  return {
    change,
    diff:
      change === 'unchanged'
        ? ''
        : lineDiff(
            before?.toString('utf8') ?? '',
            after?.toString('utf8') ?? '',
          ),
  };
}

/** The files `action` would leave behind, or a reason it cannot run. */
function projectedFiles(
  action: ProposalAction,
  target: ItemTarget,
  snapshot: ItemSnapshot,
): { files: Map<string, Buffer>; problem: string | null } {
  switch (action.type) {
    case 'write_item':
      return {
        files: new Map(
          action.files.map((f) => [f.path, Buffer.from(f.content, 'utf8')]),
        ),
        problem: null,
      };
    case 'delete_item':
      return { files: new Map(), problem: null };
    case 'none':
      return { files: snapshot.files, problem: null };
    case 'merge_task':
      return {
        files: snapshot.files,
        problem: 'merge_task cannot run on a skill or rule',
      };
    case 'set_prompt':
      return {
        files: snapshot.files,
        problem: 'set_prompt cannot run on a skill or rule',
      };
    case 'mark_local': {
      const entry = itemEntryFile(target.kind, target.name);
      const current = snapshot.files.get(entry);
      if (!snapshot.exists) {
        return { files: snapshot.files, problem: 'The item does not exist' };
      }
      if (snapshot.symlink) {
        return {
          files: snapshot.files,
          problem:
            'The item is a generated link to a shared file, not a local copy',
        };
      }
      if (!current) {
        return { files: snapshot.files, problem: `"${entry}" is missing` };
      }
      const next = new Map(snapshot.files);
      next.set(
        entry,
        Buffer.from(setLocalFrontmatter(current.toString('utf8'))),
      );
      return { files: next, problem: null };
    }
  }
}

/** Why an action must not run on an entry whose content cannot be verified. */
export function unverifiableReason(
  action: ProposalAction,
  snapshot: ItemSnapshot,
): string | null {
  if (action.type === 'none') return null;
  if (snapshot.contentHidden) {
    return 'The current entry links to a file outside the project and the trusted template folders (PROPOSAL_TEMPLATE_ROOTS). The Board cannot show or verify its content, so this cannot be applied here.';
  }
  if (snapshot.incomplete) {
    return `The current item is too large or complex to show and verify in full (${snapshot.incomplete}), so this cannot be applied here.`;
  }
  return null;
}

export function previewAction(
  action: ProposalAction,
  target: ItemTarget,
  snapshot: ItemSnapshot,
): ActionPreview {
  const projected = projectedFiles(action, target, snapshot);
  const after = projected.files;
  const problem = unverifiableReason(action, snapshot) ?? projected.problem;
  const paths = [
    ...new Set([...snapshot.files.keys(), ...after.keys()]),
  ].sort();
  const files: PreviewFile[] = [];
  if (action.type !== 'none') {
    for (const rel of paths) {
      files.push({
        path: rel,
        ...fileChange(snapshot.files.get(rel), after.get(rel)),
      });
    }
  }
  return {
    actionType: action.type,
    targetPath: target.itemPath,
    exists: snapshot.exists,
    replacesSymlink: snapshot.symlink && action.type === 'write_item',
    symlinkTarget: snapshot.symlinkTarget,
    contentHidden: snapshot.contentHidden,
    files,
    problem,
  };
}
